def my_transform(grid):
    from collections import Counter
    def determine_background(grid):
        all_vals = [cell for row in grid for cell in row]
        return Counter(all_vals).most_common(1)[0][0]

    bg = determine_background(grid)
    out_h, out_w = len(grid) // 3, len(grid[0]) // 3
    result = []
    for i in range(out_h):
        row = []
        for j in range(out_w):
            r_start, c_start = i * 3, j * 3
            output_val = None
            for dr in range(3):
                for dc in range(3):
                    val = grid[r_start + dr][c_start + dc]
                    if val != bg:
                        output_val = val
                        break
                if output_val:
                    break
            if output_val is None:
                output_val = bg  # Default to bg
            row.append(output_val)
        result.append(row)
    return result

